import { kuralSections } from './kuralStructure.js';
import { lookup } from '../i18n/index.js';
import { runtimeTranslation } from '../i18n/translationEngine.js';

/**
 * Access to all 1330 Thirukkural couplets in src/data/thirukkural.json (generated by
 * scripts/build-thirukkural.mjs). The JSON is bundled as its own chunk and loaded the
 * first time the scroll opens, so the main page stays light.
 */

let request = null;
export function loadKurals() {
  request ??= import('./thirukkural.json').then((module) => module.default.kurals);
  // Let a later attempt retry after a failure (e.g. a dropped connection).
  request.catch(() => {
    request = null;
  });
  return request;
}

/**
 * The kurals in other languages: src/data/kurals/<code>.json, a two-line rendering and a meaning
 * for each number ({ "1": { "translation", "meaning" } }), each file its own chunk, fetched only
 * when the museum is in that language (maintained with scripts/kural-translations.mjs).
 * English and Tamil are in thirukkural.json itself.
 */
const KURAL_PACKS = import.meta.glob('./kurals/*.json', { import: 'default' });
const kuralRequests = new Map();
/** Whether there is a translation of the kurals into a language. */
export const hasKuralTranslation = (code) => Boolean(KURAL_PACKS[`./kurals/${code}.json`]);
/** Resolves to the language's kural translations, or null if there are none (yet). */
export function loadKuralTranslation(code) {
  const load = KURAL_PACKS[`./kurals/${code}.json`];
  if (!load) return Promise.resolve(null);
  if (!kuralRequests.has(code)) {
    const request = load();
    request.catch(() => kuralRequests.delete(code));
    kuralRequests.set(code, request);
  }
  return kuralRequests.get(code);
}

/**
 * For a kural with no translation file entry in a language: its English rendering and meaning
 * machine-translated by the runtime service (see src/i18n/translationEngine.js), as a `local`
 * — undefined until both have arrived (asking for them meanwhile), or when there is no service.
 * Only the kural on show is asked for, never all 1330.
 */
export function machineLocal(kural, lang) {
  if (!kural || kural.local || !runtimeTranslation || lang === 'en' || lang === 'ta') return kural?.local;
  const lines = String(kural.translation ?? '').split(/;\s*/).filter(Boolean).map((line) => lookup(line, lang));
  const meaning = kural.explanation ? lookup(kural.explanation, lang) : undefined;
  if (!lines.length || lines.some((line) => !line) || !meaning) return undefined;
  return { lang, translation: lines.join('\n'), meaning, machine: true };
}

/** The kurals with their translation attached as `local` ({ lang, translation, meaning }) where it exists. */
export const withTranslation = (kurals, translations, lang) =>
  kurals && translations ? kurals.map((kural) => (translations[kural.number] ? { ...kural, local: { lang, ...translations[kural.number] } } : kural)) : kurals;

/** The 133 chapters (அதிகாரங்கள்) in order, each with its section (பால்) and group (இயல்). */
export const chapters = kuralSections.flatMap((section) =>
  section.groups.flatMap((group) => group.chapters.map((chapter) => ({ ...chapter, section, group }))),
);

/** Every chapter has exactly ten kurals. */
export const chapterOf = (number) => chapters[Math.ceil(number / 10) - 1];

export const TOTAL_KURALS = 1330;

export const SEARCH_LIMIT = 40;

/** Number lookups jump straight to a kural; words search Tamil, transliteration, English and (when loaded) the chosen language. */
export function searchKurals(kurals, query, limit = SEARCH_LIMIT) {
  const term = query.trim().toLocaleLowerCase();
  if (/^\d+$/.test(term)) return kurals.filter((k) => String(k.number).startsWith(term)).slice(0, limit);
  if (term.length < 2) return [];
  const results = [];
  for (const kural of kurals) {
    const haystack = `${kural.tamilLine1} ${kural.tamilLine2} ${kural.transliteration} ${kural.translation} ${kural.explanation} ${kural.studentMeaning?.en ?? ''} ${kural.studentMeaning?.ta ?? ''} ${kural.local?.translation ?? ''} ${kural.local?.meaning ?? ''}`.toLocaleLowerCase();
    if (haystack.includes(term)) results.push(kural);
    if (results.length >= limit) break;
  }
  return results;
}
